/** An interface a dependent package references by name. */
export interface Widget {
    id: string;
    label: string;
}

/** A generic of arity 1: the templated name has to carry the argument the reference applies. */
export interface Box<T> {
    value: T;
}

/** An object alias, declared under its own name rather than expanded at each use. */
export type WidgetPair = {
    left: Widget;
    right: Widget;
};
